// 마지막 확인 시간 이후 신규 리뷰 필터
const lastCheck = $vars.LAST_CHECK_TIME || new Date(0).toISOString();
const reviews = [];

// 네이버 리뷰 파싱 (정규식)
const naverHtml = $('네이버 플레이스 리뷰 수집').item(0).json.data;
const naverMatches = naverHtml.matchAll(/class="pui__vn15t2"[^>]*>([^<]+)<[^>]+class="pui__wMnit8"[^>]*>([^<]+)/g);
for (const m of naverMatches) {
  reviews.push({ source: '네이버', author: m[1].trim(), content: m[2].trim() });
}

// 카카오 리뷰 파싱
const kakaoHtml = $('카카오맵 리뷰 수집').item(0).json.data;
const kakaoMatches = kakaoHtml.matchAll(/class="review_cont"[^>]*>([\s\S]*?)<\/p>/g);
for (const m of kakaoMatches) {
  reviews.push({ source: '카카오', author: '익명', content: m[1].replace(/<[^>]+>/g, '').trim() });
}

return reviews.map(r => ({ json: r }));
